/**
 * Regenerates supabase/migrations/0002_seed_catalog.sql from lib/catalog.ts
 * so the database mirrors the occasions/templates shipped in code.
 *   npx tsx scripts/gen-seed.ts
 */
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { OCCASIONS, TEMPLATES } from "../lib/catalog";

const q = (s: string) => `'${s.replaceAll("'", "''")}'`;
const arr = (xs: string[]) => `array[${xs.map(q).join(", ")}]::text[]`;

const lines: string[] = [
  "-- Generated by scripts/gen-seed.ts — do not edit by hand.",
  "-- Upserts the occasion + template catalog. Safe to re-run.",
  "",
  "insert into public.occasions (slug, name, tagline, grp, sort_order) values",
  OCCASIONS.map((o, i) => `  (${q(o.slug)}, ${q(o.name)}, ${q(o.tagline)}, ${q(o.group)}, ${i})`).join(",\n"),
  "on conflict (slug) do update set name = excluded.name, tagline = excluded.tagline, grp = excluded.grp, sort_order = excluded.sort_order;",
  "",
  "insert into public.templates (slug, title, format, style, occasions, relationships, is_premium) values",
  TEMPLATES.map(
    (t) => `  (${q(t.slug)}, ${q(t.title)}, ${q(t.format)}, ${q(t.style)}, ${arr(t.occasions)}, ${arr(t.relationships)}, ${t.premium})`,
  ).join(",\n"),
  "on conflict (slug) do update set title = excluded.title, format = excluded.format, style = excluded.style,",
  "  occasions = excluded.occasions, relationships = excluded.relationships, is_premium = excluded.is_premium;",
  "",
];

const out = join(process.cwd(), "supabase/migrations/0002_seed_catalog.sql");
writeFileSync(out, lines.join("\n"));
console.log(`Wrote ${OCCASIONS.length} occasions and ${TEMPLATES.length} templates → ${out}`);
